candidates.raw:
    adcs_quat_t q_hat, dq, next;
    double theta, half, s, nw;

    if ((q == NULL) || (w == NULL) || (out == NULL)) {
        if (out != NULL) {
            *out = (adcs_quat_t){1, 0, 0, 0};
        }
        return ADCS_E_NULL;
    }

    if ((!adcs_is_finite_vec3(w)) || (!isfinite(dt)) || (dt < 0.0)) {
        *out = (adcs_quat_t){1, 0, 0, 0};
        return ADCS_E_RANGE;
    }

    if (adcs_quat_normalize(q, &q_hat) != ADCS_OK) {
        *out = (adcs_quat_t){1, 0, 0, 0};
        return ADCS_E_DEGENERATE;
    }

    nw = adcs_vec3_norm(w);
    theta = nw * dt;
    if (nw > ADCS_EPS_NORM) {
        half = 0.5 * theta;
        s = sin(half) / nw;
        dq = (adcs_quat_t){cos(half), s * w->x, s * w->y, s * w->z};
    } else {
        dq = (adcs_quat_t){1, 0, 0, 0};
    }

    next = adcs_quat_multiply(&dq, &q_hat);

    if (adcs_quat_normalize(&next, out) != ADCS_OK) {
        *out = (adcs_quat_t){1, 0, 0, 0};
        return ADCS_E_DEGENERATE;
    }

    if (out->w < 0.0) {
        out->w = -out->w;
        out->x = -out->x;
        out->y = -out->y;
        out->z = -out->z;
    }

    return ADCS_OK;
}

